import { z } from "zod";
import type { WeekMealType } from "@/lib/constants";
import { REQUIRED_JUNK_CATEGORIES, sumIngredientMacros } from "@/lib/domain/mealPlanValidation";
import type { ListCategory, Macros, MealInput } from "@/lib/types";

// The shapes Claude returns. Each meal type is generated by its own call, and the junk
// list by another. Junk categories are fixed object keys so their order can't come back
// wrong. Meal-level macros are left out on purpose: toMealInput sums them from the
// ingredients.

const MacrosSchema = z.object({
  cal: z.number(),
  p: z.number(),
  c: z.number(),
  f: z.number(),
  fiber: z.number(),
});

const IngredientSchema = z.object({
  name: z.string(),
  quantity: z.string(),
  category: z.enum(["pro", "base", "veg", "engine"]),
  macros: MacrosSchema,
});

const GeneratedMealSchema = z.object({
  name: z.string(),
  build: z.object({
    pro: z.array(z.string()),
    base: z.array(z.string()),
    veg: z.array(z.string()),
    engine: z.array(z.string()),
  }),
  ingredients: z.array(IngredientSchema),
});

/** One call's worth of meals, all the same type. The count is checked after parsing. */
export const GeneratedMealsSchema = z.object({
  meals: z.array(GeneratedMealSchema),
});

const JunkItemSchema = z.object({
  n: z.string(),
  q: z.string(),
});

export const GeneratedJunkListSchema = z.object({
  junkList: z.object({
    "Coffee/Creamer": z.array(JunkItemSchema),
    "Beer/Wine": z.array(JunkItemSchema),
    Chips: z.array(JunkItemSchema),
    Sweets: z.array(JunkItemSchema),
    "Frozen Food": z.array(JunkItemSchema),
    "Frozen Treats": z.array(JunkItemSchema),
    "Beverages/Drinks": z.array(JunkItemSchema),
  }),
});

export type GeneratedMeal = z.infer<typeof GeneratedMealSchema>;
export type GeneratedMeals = z.infer<typeof GeneratedMealsSchema>;
export type GeneratedJunkList = z.infer<typeof GeneratedJunkListSchema>;

/** Converts one of Claude's meals into the app's MealInput. */
export function toMealInput(meal: GeneratedMeal, type: WeekMealType): MealInput {
  const ingredients = meal.ingredients.map((ingredient) => ({
    name: ingredient.name.trim(),
    quantity: ingredient.quantity.trim(),
    category: ingredient.category,
    macros: roundMacros(ingredient.macros, 1),
  }));

  return {
    type,
    name: meal.name.trim(),
    build: {
      pro: cleanList(meal.build.pro),
      base: cleanList(meal.build.base),
      veg: cleanList(meal.build.veg),
      engine: cleanList(meal.build.engine),
    },
    ingredients,
    // Meal macros are stored as integers.
    macros: roundMacros(sumIngredientMacros(ingredients), 0),
  };
}

/** Converts Claude's junk list into the app's ordered categories. */
export function toJunkList(generated: GeneratedJunkList): ListCategory[] {
  return REQUIRED_JUNK_CATEGORIES.map((category) => ({
    category,
    items: generated.junkList[category]
      .map((item) => ({ n: item.n.trim(), q: item.q.trim() }))
      .filter((item) => item.n)
      .map((item) => (item.q ? item : { n: item.n })),
  }));
}

function cleanList(values: string[]): string[] {
  return values.map((value) => value.trim()).filter(Boolean);
}

function roundMacros(macros: Macros, decimals: number): Macros {
  const factor = 10 ** decimals;
  const round = (value: number) => Math.round(value * factor) / factor;
  return {
    cal: round(macros.cal),
    p: round(macros.p),
    c: round(macros.c),
    f: round(macros.f),
    fiber: round(macros.fiber),
  };
}
